{"code": "export async function main(input: any) {
  const { issues } = await sdk.sentry.listIssues({ project: "web" });
  const candidates = issues.filter(i => i.status === "unresolved" && i.count >= 50);
  const results: any[] = [];
  for (const issue of candidates) {
    const search = await sdk.linear.searchIssues({ query: issue.culprit });
    const blame = await sdk.github.getBlame({ file: issue.filename, line: issue.lineNumber });
    results.push({ issue: issue.id, title: issue.title, culprit: issue.culprit, filename: issue.filename, line: issue.lineNumber, search, blame });
  }
  // Also broader searches to be safe
  const broader = await sdk.linear.searchIssues({ query: "checkout.ts" });
  const broader2 = await sdk.linear.searchIssues({ query: "sync-worker.ts" });
  return { checked: issues.length, candidates: candidates.length, results, broader, broader2 };
}"}

{"code": "export async function main(input: any) {
  const queries = ["computeTotal", "flushQueue", "checkout", "sync-worker", "Sentry", "TypeError", "TimeoutError", "total"];
  const out: any = {};
  for (const q of queries) {
    out[q] = (await sdk.linear.searchIssues({ query: q })).issues.map(i => ({ id: i.id, identifier: i.identifier, title: i.title, description: i.description }));
