{"code": "export async function main(input: any) {
  const { issues } = await sdk.sentry.listIssues({ project: "web" });
  const candidates = issues.filter(i => i.status === "unresolved" && i.count >= 50);

  const created: any[] = [];
  const skipped: any[] = [];
  for (const issue of candidates) {
    const mention = await sdk.linear.searchIssues({ query: issue.culprit });
    if (mention.issues.length > 0) { skipped.push({ issue: issue.id, because: mention.issues }); continue; }
    const blame = await sdk.github.getBlame({ file: issue.filename, line: issue.lineNumber });
    const placeholder = await sdk.linear.createIssue({
      title: `[Sentry] ${issue.title}`,
      description: issue.culprit,
      assigneeEmail: blame.authorEmail,
    });
    created.push(placeholder);
  }
  return { checked: issues.length, candidates: candidates.map(i => i.id), skipped, created };
}"}

